def transform(grid):
    """Replace large solid monochrome rectangular patches with 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marked = [[False] * w for _ in range(h)]
    # Every patch in the demonstrations is a uniform rectangle at least
    # 5x5. Use 4x4 windows to include any smaller planted rectangle.
    rh = cw = 4
    for r in range(h - rh + 1):
        for c in range(w - cw + 1):
            color = grid[r][c]
            if all(grid[i][j] == color
                   for i in range(r, r + rh)
                   for j in range(c, c + cw)):
                for i in range(r, r + rh):
                    for j in range(c, c + cw):
                        marked[i][j] = True
    for r in range(h):
        for c in range(w):
            if marked[r][c]:
                out[r][c] = 4
    return out
